questionvariables.text:
/* Type 1 compound-argument equation: c*cos(n*theta) = c*k for 0 <= theta <= 360.
   n in {2, 3, 1/2}; k one of six exact values (no awkward surds); c in {2, 4}.
   3 x 6 x 2 = 36 distinct variants. Solutions are found for u = n*theta first. */
klist : [[1/2, 60], [-1/2, 120], [sqrt(3)/2, 30], [-sqrt(3)/2, 150], [sqrt(2)/2, 45], [-sqrt(2)/2, 135]];
kb : rand(klist);
k : kb[1];
beta : kb[2];                 /* the calculator value cos^(-1)(k), between 0 and 180 */
n : rand([2, 3, 1/2]);
c : rand([2, 4]);
rhs : c*k;

/* (a) range of u = n*theta */
umax : 360*n;
umax_wrong : 360/n;           /* divided instead of multiplied */

/* (b) all u in [0, umax] with cos(u) = k: beta and 360 - beta, then add 360 while still in range */
solsU : if n = 1/2 then [beta] else if n = 2 then [beta, 360-beta, 360+beta, 720-beta]
        else [beta, 360-beta, 360+beta, 720-beta, 720+beta, 1080-beta];
nsol : length(solsU);
firstturn : [beta, 360-beta];  /* solutions of cos(u) = k in 0..360 only */
/* solutions for the opposite sign, cos(u) = -k (the common sign slip) */
bw : 180 - beta;
wsolsU : if n = 1/2 then [bw] else if n = 2 then [bw, 360-bw, 360+bw, 720-bw]
         else [bw, 360-bw, 360+bw, 720-bw, 720+bw, 1080-bw];

/* (c) theta = u/n */
solsT : solsU/n;
solsT_disp : if n = 2 and (beta = 45 or beta = 135) then float(solsT) else solsT;
nsT : float(sort(solsT));
nsU : float(sort(solsU));
nsW : float(sort(wsolsU));
nsF : float(sort(firstturn));
nsUn : float(sort(solsU*n));  /* multiplied by n instead of dividing */

feedbackvariables.text:
/* the student's values as a sorted list of numbers (a list or a set is accepted, in any order) */
sl : if listp(ans_u) then ans_u else if setp(ans_u) then listify(ans_u) else [ans_u];
L : float(sort(sl));
okU : if length(L) = length(nsU) then is(lmax(abs(L - nsU)) <= 0.01) else false;
ftU : if length(L) = length(nsF) then is(lmax(abs(L - nsF)) <= 0.01) else false;
wU : if length(L) = length(nsW) then is(lmax(abs(L - nsW)) <= 0.01) else false;
ft_short : is(ftU and n > 1);
ft_out : is(ftU and n < 1);

/* the student's values as a sorted list of numbers (a list or a set is accepted, in any order) */
sl : if listp(ans_t) then ans_t else if setp(ans_t) then listify(ans_t) else [ans_t];
L : float(sort(sl));
okT : if length(L) = length(nsT) then is(lmax(abs(L - nsT)) <= 0.01) else false;
gaveU : if length(L) = length(nsU) then is(lmax(abs(L - nsU)) <= 0.01) else false;
multN : if length(L) = length(nsUn) then is(lmax(abs(L - nsUn)) <= 0.01) else false;
/* follow-through: the student's own (b) values converted correctly */
slu : if listp(ans_u) then ans_u else if setp(ans_u) then listify(ans_u) else [ans_u];
Lfu : float(sort(slu/n));
ecf : if length(L) = length(Lfu) then is(lmax(abs(L - Lfu)) <= 0.01) else false;
